using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;public static class SaveFramingEF{public static string Main(){if(Application.isPlaying)throw new Exception("Edit Mode required");var list=new List<object>();foreach(var path in new[]{"Assets/M/Scene/Elevator_Safety_Prototype.unity","Assets/M/Scene/Elevator_Safety_ObjectInteraction_Test.unity"}){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var lesson=Object.FindFirstObjectByType<ElevatorLesson>();var map=lesson.presentation.space.sportsCentre;if(!map||!lesson.GetComponent<ElevatorCameraEffects>())throw new Exception("Missing camera wiring");map.interiorReframeSeconds=.6f;EditorUtility.SetDirty(map);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");list.Add(new{path,mode=lesson.scenario.objectGuidedScene,duration=map.interiorReframeSeconds,targets=lesson.CollectObservations().Count(o=>o.outlineTarget),missingScripts=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))});}EditorSceneManager.OpenScene("Assets/M/Scene/Elevator_Safety_Prototype.unity",OpenSceneMode.Single);UnityEditor.EditorApplication.ExecuteMenuItem("Window/General/Game");var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=true,scenes=list},Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorCinematicFraming_20261030~/SavedScenes.json",report);return report;}}